// "Mañana" es el día siguiente en la zona del negocio, no en UTC: a las 10:00 de Madrid
// son las 9:00 (o las 8:00) en UTC, y un día calculado en UTC se come o se inventa las
// citas de la primera y la última hora.
const c = $json;
const tz = c.tenant_timezone || 'Europe/Madrid';
const ahora = DateTime.now().setZone(tz);
const manana = ahora.plus({ days: 1 });
// El ajuste llega como texto desde tenant.env. Solo un "true" explícito lo enciende:
// mandar mensajes de pago a clientes reales no puede depender de una lectura laxa.
const activo = String(c.recordatorio_citas || '').trim().toLowerCase() === 'true';
return [{ json: { ...c, tz, activo,
  desde: manana.startOf('day').toUTC().toISO(),
  hasta: manana.endOf('day').toUTC().toISO(),
  hoy_desde: ahora.startOf('day').toUTC().toISO(),
} }];

// Un recordatorio POR CITA de mañana, al teléfono del cliente. Lo que no se manda
// queda en `_omitidos` con su motivo: es lo que se mira cuando alguien dice "a mí no
// me llegó".
const h = $('Code · Mañana').first().json;
const tz = h.tz;

// Si una consulta falla, esto falla A LA VISTA. Con la lista de mensajes de hoy vacía
// por un 403, una segunda pasada mandaría otra vez todos los recordatorios.
const lista = (nombre) => {
  const r = $(nombre).first().json || {};
  const code = r.statusCode || 0;
  if (code < 200 || code >= 300) {
    const msg = (r.body && r.body.errors && r.body.errors[0] && r.body.errors[0].message) || code;
    throw new Error(`${nombre}: Directus devolvió ${code} (${msg})`);
  }
  return (r.body && r.body.data) || [];
};
const citas = lista('HTTP · Citas de mañana');
const yaHoy = lista('HTTP · Recordatorios de hoy');

const limpio = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digitos = (v) => limpio(v).replace(/[^\d]/g, '');
// Mismo criterio que el resto: 9 dígitos que empiezan por 6/7/8/9 son españoles sin el 34.
const aE164 = (d) => (/^[6789]\d{8}$/.test(d) ? `34${d}` : d);
// Un fijo español (34 8xx / 34 9xx) no tiene WhatsApp. Si la ficha no dice lo
// contrario (`can_whatsapp`), no se intenta: Meta lo rechazaría igual.
const esFijoEs = (d) => /^34[89]\d{8}$/.test(d);

const telefonoDe = (contacto) => {
  const tels = ((contacto && contacto.phones) || [])
    .map((p) => ({ ...p, _d: aE164(digitos(p.phone_normalized || p.phone_number)) }))
    .filter((p) => p._d);
  const orden = (p) => (p.can_whatsapp === true ? 0 : 2) + (p.is_primary === true ? 0 : 1);
  const validos = tels.filter((p) => p.can_whatsapp === true || !esFijoEs(p._d))
    .sort((a, b) => orden(a) - orden(b));
  return validos.length ? validos[0]._d : '';
};

// Lo que ya salió HOY, para que una segunda pasada (una ejecución a mano, un reinicio a
// la hora justa) no mande dos veces lo mismo. Se reconoce por hilo + "tu cita del <día>
// a las <hora>", que es el texto que WHATSAPP · Enviar plantilla guarda: si la cita se
// movió, el texto es otro y sí toca recordarla. Solo cuentan los `enviado`: un envío
// fallido (p. ej. plantilla aún sin aprobar) se puede repetir a mano el mismo día.
const enviados = new Set(yaHoy
  .filter((m) => m.estado_envio === 'enviado')
  .map((m) => `${(m.session_id && m.session_id.session_key) || ''}|${limpio(m.texto)}`));
const yaEnviado = (tel, frase) => [...enviados].some((k) =>
  k.startsWith(`whatsapp:${tel}|`) && k.includes(frase));

const hoyDesde = DateTime.fromISO(h.hoy_desde);
const salida = [];
const omitidos = [];
for (const a of citas) {
  const ct = (a.contact_id && typeof a.contact_id === 'object') ? a.contact_id : null;
  const inicio = DateTime.fromISO(a.start_at).setZone(tz).setLocale('es');
  const dia = inicio.toFormat("cccc d 'de' LLLL");
  const hora = inicio.toFormat('HH:mm');
  const base = { cita: a.id, hora };
  if (!ct) { omitidos.push({ ...base, motivo: 'sin_contacto' }); continue; }
  // Pedida hoy para mañana: el cliente acaba de hablar con nosotros y tiene su
  // confirmación de hace unas horas. Un recordatorio ahí es ruido, y se paga.
  if (a.created_at && DateTime.fromISO(a.created_at) >= hoyDesde) {
    omitidos.push({ ...base, motivo: 'reservada_hoy' }); continue;
  }
  // La plantilla empieza por "Hola {{1}}" y Meta no admite un parámetro vacío.
  const nombre = limpio(ct.first_name);
  if (!nombre) { omitidos.push({ ...base, motivo: 'sin_nombre' }); continue; }
  const telefono = telefonoDe(ct);
  if (!telefono) { omitidos.push({ ...base, motivo: 'sin_movil' }); continue; }
  if (yaEnviado(telefono, `tu cita del ${dia} a las ${hora}`)) {
    omitidos.push({ ...base, motivo: 'ya_enviado_hoy' }); continue;
  }
  salida.push({ json: {
    cita: a.id,
    telefono,
    plantilla: 'aegora_recordatorio_cita',
    parametros: JSON.stringify([nombre, dia, hora]),
    contact_id: ct.id,
  } });
}

if (!salida.length) {
  return [{ json: { _nadie: true, citas: citas.length, omitidos } }];
}
salida[0].json._omitidos = omitidos;
return salida;

// Una línea que diga qué ha pasado: cuántos recordatorios salieron, cuáles fallaron
// y cuáles no se intentaron y por qué.
const items = $input.all().map((i) => i.json);
if (items.length === 1 && items[0]._nadie) {
  return [{ json: { enviados: 0, fallidos: [], citas: items[0].citas, omitidos: items[0].omitidos } }];
}
let omitidos = [];
try { omitidos = $('Code · Recordatorios').first().json._omitidos || []; } catch (e) { omitidos = []; }
return [{ json: {
  enviados: items.filter((x) => x.enviado).length,
  fallidos: items.filter((x) => !x.enviado).map((x) => x.error || x.motivo || 'desconocido'),
  omitidos,
} }];
